import {roomScene,researchText} from './lab-scene.js';
import {researchGrade} from './engine.js';
const labels={study:'문헌 공부',coursework:'교과목 공부',experiment:'연구',analysis:'데이터 분석',paper:'논문 쓰기',conference:'학회에서 배우기',free:'자율 시간',travel:'여행·새로운 경험',rest:'휴식',language:'어학 및 전달 연습',industry:'산학과제 수행 · RA',video:'과학 콘텐츠',teach:'수업보조 · TA',unfinished:'계획 다시 살피기'};
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function weeklyScene(state,result,index){
 const id=result.actual,scientific=Number.isFinite(result.successRate),success=scientific?result.successRate>=.4:result.performed;
 const status=result.proposed==='free'&&result.performed?({coursework:'자율 학습 · 교과목 복습',study:'자율 학습 · 문헌 검토',experiment:'자율 연구 · 가설 검증',analysis:'자율 연구 · 데이터 분석',rest:'자율 회복 활동 완료',travel:'자율 활동 · 여행과 탐색'})[result.autonomous]:!result.performed?'계획한 활동 미완료':result.outcome==='presentation_failed'?'발표 준비와 전달에 어려움':result.outcome==='inconclusive'?'이번 시도에서 확인 가능한 진전 없음':id==='rest'?'자율 회복 활동을 마쳤습니다':id==='conference'?(result.outcome==='presented'?'연구 발표 완료':'학술대회 청강 완료'):'계획한 활동을 수행했습니다';
 const progress=result.progress>0?`연구 진척 Δ +${result.progress.toFixed(1)}`:scientific?(id==='coursework'?'교과 학습 · 복습과 점검을 기록했습니다.':'연구 진척 0 · 시도도 기록에 남습니다.'):id==='rest'?'다음 주를 위한 여유':'배운 것을 기록했습니다.';
 return `<div class="weekly-stage ${success?'week-success':'week-trying'} task-${id}" aria-label="${index+1}주차 수행 결과"><div class="week-scene-header"><span>${index+1}주차 / ${state.lastReport?.results.length??state.plan.length}</span><strong>${id==='experiment'&&state.professorProfile.labMode==='dry'?'계산·모델링':labels[id]||labels[result.proposed]}</strong></div>${roomScene(state,result,index)}<div class="week-outcome"><strong>${escape(scientific?`${researchGrade(result.successRate)} · 달성률 ${Math.round(result.successRate*100)}%`:status)}</strong><p>${escape(progress)}</p><ol class="week-dots" aria-label="주별 진행">${Array.from({length:state.lastReport?.results.length??state.plan.length},(_,i)=>`<li class="${i<index?'done':i===index?'current':''}">${i+1}주</li>`).join('')}</ol></div></div>`;
}
